function compileTemplate(source, translated) {
	const names = []; let pattern = ""; let last = 0;
	for (const match of source.matchAll(PLACEHOLDER)) {
		pattern += source.slice(last, match.index).replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
		pattern += "([\\s\\S]+?)"; names.push(match[1]); last = match.index + match[0].length;
	}
	pattern += source.slice(last).replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
	const slots = new Map(names.map((name, index) => [name, index + 1]));
	return { re: new RegExp(`^${pattern}$`), render: (match) => translated.replace(PLACEHOLDER, (token, name) => {
		const slot = slots.get(name); return slot ? match[slot] : token;
	}) };
}
for (const entry of DIALOGUE_DATA) {
	if (entry.d) DYNAMIC_OUTPUT.push(compileTemplate(entry.s, entry.v)); else STATIC_OUTPUT.set(entry.s, entry.v);
}

