function translateBareOutput(text) {
	const curated = CURATED_OUTPUT.get(text); if (curated !== undefined) return curated;
	for (const [pattern, replacement] of OUTPUT_RULES) if (pattern.test(text)) return text.replace(pattern, replacement);
	const exact = STATIC_OUTPUT.get(text); if (exact !== undefined) return exact;
	for (const template of DYNAMIC_OUTPUT) { const match = text.match(template.re); if (match) return template.render(match); }
	return text;
}
export function translateOutput(text) {
	if (typeof text !== "string" || text.length === 0) return text;
	const direct = translateBareOutput(text); if (direct !== text) return direct;
	const decorated = text.match(/^(<?eVerity?r>\s*)([\s\S]+)$/);
	if (decorated) { const body = translateBareOutput(decorated[2]); return body === decorated[2] ? text : decorated[1] + body; }
	return text;
}

